SELECT e.*, c.company_name AS company_name_belong, c2.company_name AS company_name_assign FROM m_employee e LEFT JOIN m_company c ON e.company_id = c.company_id LEFT JOIN t_assignment a ON a.emp_id = e.emp_id AND a.contract_end_date is null LEFT JOIN m_company c2 ON a.company_id = c2.company_id
emp_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY ${sort} ${order}

